 if($name===""||!filter_var($email,FILTER_VALIDATE_EMAIL)||$cid===""||strlen($pw)<8) $error="Complete all fields and use a password of at least 8 characters.";
 else try{$q=$pdo->prepare("INSERT INTO users(full_name,email,college_id,password_hash,role,is_approved) VALUES(?,?,?,?,'student',1)");$q->execute([$name,$email,$cid,password_hash($pw,PASSWORD_DEFAULT)]);flash("Student account created. You can now sign in.");header("Location: login.php");exit;}catch(PDOException $e){$error="That email or college ID is already registered.";}
